 * @hidden N
*/
scwin.setCfiAttr4 = function () {
    /* sdd-asis-lifecycle:begin fn_SetCfiAttr4 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const sTmp = $('input[name=rd_fncUlyTpCd]:checked').val();
    if (sTmp === "1") {
        $c.util.getComponent('slc_attr04').setValue("S");
    } else {
        if (sTmp === "2") {
            $c.util.getComponent('slc_attr04').setValue("B");
        } else {
            if (sTmp === "3") {
                $c.util.getComponent('slc_attr04').setValue("I");
            } else {
                if (sTmp === "4") {
                    $c.util.getComponent('slc_attr04').setValue("T");
                } else {
                    if (sTmp === "5") {
                        $c.util.getComponent('slc_attr04').setValue("D");
                    } else {
                        if (sTmp === "6") {
                            $c.util.getComponent('slc_attr04').setValue("C");
                        } else {
                            if (sTmp === "9") {
                                $c.util.getComponent('slc_attr04').setValue("M");
                            }
                        }
                    }
                }
            }
        }
    }
    scwin.chg_attr();
    /* sdd-asis-lifecycle:end */
};


